import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
  Container, Typography, Box, Button, IconButton,
  Card, CardContent, Grid, ButtonGroup
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import RemoveIcon from '@mui/icons-material/Remove';
import { selectCartItems, selectCartTotal, removeFromCart, updateQuantity } from '../features/cartSlice';
import { useNavigate } from 'react-router-dom';

const CartPage = () => {
  const dispatch = useDispatch();
  const cartItems = useSelector(selectCartItems);
  const total = useSelector(selectCartTotal);

  const handleQuantityChange = (productId, newQuantity) => {
    dispatch(updateQuantity({ id: productId, quantity: newQuantity }));
  };

  const handleRemove = (productId) => {
    dispatch(removeFromCart(productId));
  };

  if (cartItems.length === 0) {
    return (
      <Container sx={{ py: 8, textAlign: 'center' }}>
        <Typography variant="h5" gutterBottom>Your cart is empty</Typography>
        <Button variant="contained" color="primary" href="/products">
          Continue Shopping
        </Button>
      </Container>
    );
  }

  return (
    <Container sx={{ py: 4 }}>
      <Typography variant="h4" gutterBottom sx={{ mb: 4 }}>
        Shopping Cart
      </Typography>
      
      {cartItems.map((item) => (
        <Card key={item.id} sx={{ mb: 2, borderRadius: 2 }}>
          <CardContent>
            <Grid container alignItems="center" spacing={2}>
              <Grid item xs={12} sm={2}>
                <img 
                  src={item.image} 
                  alt={item.name} 
                  style={{ 
                    width: '100%', 
                    maxWidth: '100px',
                    height: 'auto',
                    borderRadius: '8px'
                  }} 
                />
              </Grid>
              
              <Grid item xs={12} sm={4}>
                <Typography variant="h6" gutterBottom>
                  {item.name}
                </Typography>
                <Typography color="text.secondary">
                  ${item.price}
                </Typography>
              </Grid>
              
              <Grid item xs={12} sm={3}>
                <ButtonGroup size="small" aria-label="quantity control">
                  <IconButton 
                    onClick={() => handleQuantityChange(item.id, item.quantity - 1)}
                    disabled={item.quantity <= 1}
                  >
                    <RemoveIcon />
                  </IconButton>
                  <Box sx={{ px: 2, py: 1, minWidth: '40px', textAlign: 'center' }}>
                    {item.quantity}
                  </Box>
                  <IconButton 
                    onClick={() => handleQuantityChange(item.id, item.quantity + 1)}
                  >
                    <AddIcon />
                  </IconButton>
                </ButtonGroup>
              </Grid>
              
              <Grid item xs={12} sm={2}>
                <Typography variant="h6">
                  ${(item.price * item.quantity).toFixed(2)}
                </Typography>
              </Grid>
              
              <Grid item xs={12} sm={1}>
                <IconButton 
                  color="error" 
                  onClick={() => handleRemove(item.id)}
                  aria-label="delete"
                >
                  <DeleteIcon />
                </IconButton>
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      ))}
      
      <Box sx={{ 
        mt: 4, 
        p: 3, 
        bgcolor: 'background.paper',
        borderRadius: 2,
        boxShadow: 1
      }}>
        <Grid container justifyContent="space-between" alignItems="center">
          <Grid item>
            <Typography variant="h5">
              Total: ${total.toFixed(2)}
            </Typography>
          </Grid>
          <Grid item>
            <Button 
              variant="contained" 
              color="primary" 
              size="large"
              onClick={() => navigate('/checkout')}
            >
              Proceed to Checkout
            </Button>
          </Grid>
        </Grid>
      </Box>
    </Container>
  );
};

export default CartPage;
